56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper) {
75	        this.clinicService = clinicService;
76	        this.ownerMapper = ownerMapper;
77	        this.petMapper = petMapper;
78	        this.visitMapper = visitMapper;
79	    }
80	
81	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
82	    @Override
83	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
84	        Collection<Owner> owners;
85	        if (lastName != null) {
86	            owners = this.clinicService.findOwnerByLastName(lastName);
87	        } else {
88	            owners = this.clinicService.findAllOwners();
89	        }
90	        if (owners.isEmpty()) {
91	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
92	        }
93	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
99	        Owner owner = this.clinicService.findOwnerById(ownerId);
100	        if (owner == null) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
104	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
105	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
114	        DisposableEmailValidator.validate(owner.getEmail());
115	        RegistrationDateValidator.validate(owner.getRegistrationDate());
116	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
117	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
118	        }
119	        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
120	        // and postcode are automatically the same household.
121	        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
122	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
123	        // A second owner in an existing household is a duplicate unless it declares itself a member,
124	        // which bypasses the household duplicate block.
125	        if (!sharesHousehold && this.clinicService.isHouseholdInUse(owner)) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        // Reject exact identity duplicates: when the new owner's whole identity key
129	        // (telephone|email|householdId) matches an existing one.
130	        if (this.clinicService.isIdentityKeyInUse(owner)) {
131	            return new ResponseEntity<>(HttpStatus.CONFLICT);
132	        }
133	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
134	            return new ResponseEntity<>(HttpStatus.CONFLICT);
135	        }
136	        this.clinicService.saveOwner(owner, sharesHousehold);
137	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
138	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
139	            ownerMapper.formatMembershipLevel(owner));
140	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
141	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
142	        headers.setLocation(UriComponentsBuilder.newInstance()
143	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
144	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
150	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
151	        if (currentOwner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        PostcodeValidator.validate(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
155	        DisposableEmailValidator.validate(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
156	        currentOwner.setAddress(ownerFieldsDto.getAddress());
157	        currentOwner.setCity(ownerFieldsDto.getCity());
158	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
159	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
160	        currentOwner.setLastName(ownerFieldsDto.getLastName());
161	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
162	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
163	        this.clinicService.saveOwner(currentOwner);
164	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Transactional
169	    @Override
170	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        this.clinicService.deleteOwner(owner);
176	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        HttpHeaders headers = new HttpHeaders();
187	        Pet pet = petMapper.toPet(petFieldsDto);
188	        owner.setId(ownerId);
189	        pet.setOwner(owner);
190	        pet.getType().setName(null);
191	        this.clinicService.savePet(pet);
192	        PetDto petDto = petMapper.toPetDto(pet);
193	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
194	            .buildAndExpand(pet.getId()).toUri());
195	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
201	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
202	        if (currentOwner != null) {
203	            Pet currentPet = this.clinicService.findPetById(petId);
204	            if (currentPet != null) {
205	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
206	                currentPet.setName(petFieldsDto.getName());
207	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
208	                this.clinicService.savePet(currentPet);
209	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	            }
211	        }
212	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
218	        HttpHeaders headers = new HttpHeaders();
219	        Visit visit = visitMapper.toVisit(visitFieldsDto);
220	        Pet pet = new Pet();
221	        pet.setId(petId);
222	        visit.setPet(pet);
223	        this.clinicService.saveVisit(visit);
224	        VisitDto visitDto = visitMapper.toVisitDto(visit);
225	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
226	            .buildAndExpand(visit.getId()).toUri());
227	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
228	    }
229	
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner != null) {
236	            Pet pet = owner.getPet(petId);
237	            if (pet != null) {
238	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
239	            }
240	        }
241	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	    }
243	}
