6	/**
7	 * Validates an owner's email address against a fixed blocklist of disposable-email domains.
8	 *
9	 * <p>An email is validated ONLY when present; a {@code null} or empty email is always accepted,
10	 * keeping the request contract backward-compatible. When present, its domain (the part after the
11	 * last {@code '@'}) is compared case-insensitively against the blocklist and the email is rejected
12	 * when it matches. The syntactic validity of any value present is already guaranteed by the
13	 * schema-level {@code format: email} on the request field.
14	 */
15	public final class DisposableEmailValidator {
16	
17	    /** Disposable-email domains that are not accepted (compared in lower case). */
18	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
19	        "mailinator.com", "tempmail.com", "guerrillamail.com");
20	
21	    private DisposableEmailValidator() {
22	    }
23	
24	    /**
25	     * Validate an email address, throwing when its domain is on the disposable-domain blocklist.
26	     *
27	     * @param email the owner's email, or {@code null} when none was given
28	     * @throws DisposableEmailException if a non-blank email's domain is on the blocklist.
29	     */
30	    public static void validate(String email) {
31	        if (email == null || email.isEmpty()) {
32	            return;
33	        }
34	        int at = email.lastIndexOf('@');
35	        if (at < 0 || at == email.length() - 1) {
36	            return;
37	        }
38	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
39	        if (BLOCKED_DOMAINS.contains(domain)) {
40	            throw new DisposableEmailException(email);
41	        }
42	    }
43	}
