3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Normalizes a free-text postal address into a canonical form so that differently
8	 * formatted but equivalent addresses are stored, returned and compared consistently.
9	 *
10	 * <p>The rules are:
11	 * <ul>
12	 *   <li>surrounding whitespace is trimmed and any internal run of whitespace is
13	 *       collapsed to a single space;</li>
14	 *   <li>the whole value is upper-cased;</li>
15	 *   <li>common abbreviations are expanded as whole tokens: {@code ST -> STREET},
16	 *       {@code RD -> ROAD} and {@code AVE -> AVENUE}.</li>
17	 * </ul>
18	 *
19	 * <p>So {@code '  12  main  st '} becomes {@code '12 MAIN STREET'} and
20	 * {@code '7 elm ave'} becomes {@code '7 ELM AVENUE'}.
21	 */
22	public final class AddressNormalizer {
23	
24	    /** Whole-token abbreviation expansions, keyed by the already upper-cased token. */
25	    private static final Map<String, String> ABBREVIATIONS = Map.of(
26	        "ST", "STREET",
27	        "RD", "ROAD",
28	        "AVE", "AVENUE");
29	
30	    private AddressNormalizer() {
31	    }
32	
33	    /**
34	     * Normalize a raw address to its canonical form.
35	     *
36	     * @param raw the address as supplied by the caller (any format)
37	     * @return the normalized address, or {@code null} if {@code raw} is {@code null}.
38	     *         A value consisting only of whitespace normalizes to an empty string.
39	     */
40	    public static String normalize(String raw) {
41	        if (raw == null) {
42	            return null;
43	        }
44	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
45	        if (collapsed.isEmpty()) {
46	            return collapsed;
47	        }
48	        String[] tokens = collapsed.split(" ");
49	        StringBuilder sb = new StringBuilder(collapsed.length());
50	        for (int i = 0; i < tokens.length; i++) {
51	            if (i > 0) {
52	                sb.append(' ');
53	            }
54	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
55	        }
56	        return sb.toString();
57	    }
58	}
