256	    @Override
257	    @Transactional
258	    public void saveOwner(Owner owner, boolean declaredHouseholdMember) throws DataAccessException {
259	        if (owner.isNew()) {
260	            LocalDate effectiveDate = owner.getRegistrationDate() != null
261	                ? owner.getRegistrationDate()
262	                : LocalDate.now();
263	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
264	            if (owner.getHouseholdId() == null) {
265	                owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
266	            }
267	            if (owner.getCustomerCode() == null) {
268	                owner.setCustomerCode(generateCustomerCode(owner));
269	            }
270	            if (owner.getNamesakeCount() == null) {
271	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
272	            }
273	            if (owner.getPossibleDuplicate() == null) {
274	                // A declared household member is not a suspected duplicate; otherwise flag it against
275	                // any existing member of the same household it collides with.
276	                Integer possibleDuplicateOf = declaredHouseholdMember ? null : findPossibleDuplicateOf(owner);
277	                owner.setPossibleDuplicateOf(possibleDuplicateOf);
278	                owner.setPossibleDuplicate(possibleDuplicateOf != null);
279	            }
280	        }
281	        ownerRepository.save(owner);
282	        decorateWithHouseholdMemberCount(owner);
283	    }
284	
285	    /**
286	     * Count the existing owners (before this create) that share the given first and last name,
287	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
288	     */
289	    private int countNamesakes(String firstName, String lastName) {
290	        if (firstName == null || lastName == null) {
291	            return 0;
292	        }
293	        return (int) ownerRepository.findAll().stream()
294	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
295	                && lastName.equalsIgnoreCase(owner.getLastName()))
296	            .count();
297	    }
298	
299	    /**
300	     * Build a customer code formatted {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
301	     * canonical region derived from the owner's postcode (falling back to the city-to-region
302	     * table, then {@code 'UNKNOWN'}, as resolved by {@link LocalityResolver}) and {@code HASH8}
303	     * is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the owner's
304	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). There
305	     * is no sequence number: identity is fully determined by the region and the telephone/last
306	     * name hash.
307	     */
308	    private String generateCustomerCode(Owner owner) {
309	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
310	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
311	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
312	        return region + "-" + Sha256Hex.upperHexPrefix(telephone + lastName, 8);
313	    }
314	
315	    /**
316	     * Count the existing owners whose city matches the given city, compared case-insensitively,
317	     * used by the per-city capacity rule ({@link #isCityAtCapacity}).
318	     */
319	    private long countOwnersInCity(String city) {
320	        if (city == null) {
321	            return 0L;
322	        }
323	        return ownerRepository.findAll().stream()
324	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
325	            .count();
326	    }
