346	    /**
347	     * Count the owners whose registration date equals today's business day, used by the
348	     * daily create-limit and bulk-signup rules.
349	     */
350	    private long countRegisteredToday() {
351	        LocalDate businessDay = toBusinessDay(LocalDate.now());
352	        return ownerRepository.findAll().stream()
353	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
354	            .count();
355	    }
356	
357	    /**
358	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced
359	     * to the following Monday, while a weekday is returned unchanged. Applied to the effective
360	     * registration date (whether supplied or defaulted to the server date) so that the stored
361	     * {@code registrationDate}, every value derived from it (such as the membership number's year
362	     * segment) and the per-day create-limit all use the adjusted business day.
363	     */
364	    private static LocalDate toBusinessDay(LocalDate date) {
365	        DayOfWeek day = date.getDayOfWeek();
366	        if (day == DayOfWeek.SATURDAY) {
367	            return date.plusDays(2);
368	        }
369	        if (day == DayOfWeek.SUNDAY) {
370	            return date.plusDays(1);
371	        }
372	        return date;
373	    }
