375	    @Override
376	    @Transactional(readOnly = true)
377	    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
378	        String identityKey = owner.getIdentityKey();
379	        return ownerRepository.findAll().stream()
380	            .filter(existing -> existing != owner)
381	            .map(Owner::getIdentityKey)
382	            .anyMatch(identityKey::equals);
383	    }
384	
385	    /**
386	     * Resolve the id of an existing owner that the given (not yet persisted) owner is a <em>possible</em>
387	     * duplicate of, or {@code null} when there is none. A possible duplicate belongs to an existing
388	     * owner's household (same computed {@code householdId}, i.e. same last name and postcode) while
389	     * carrying a different telephone, so it is not a hard duplicate (its identity key is unique) but is
390	     * worth flagging. When several existing owners match, the one with the lowest id is returned so the
391	     * result is deterministic. Computed once, at creation, to drive the read-only
392	     * {@code possibleDuplicate}/{@code possibleDuplicateOf} fields.
393	     */
394	    private Integer findPossibleDuplicateOf(Owner owner) {
395	        String householdId = owner.getHouseholdId();
396	        if (householdId == null) {
397	            return null;
398	        }
399	        return ownerRepository.findAll().stream()
400	            .filter(existing -> existing != owner && existing.getId() != null)
401	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
402	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
403	            .map(Owner::getId)
404	            .min(Integer::compareTo)
405	            .orElse(null);
406	    }
407	
408	    @Override
409	    @Transactional(readOnly = true)
410	    public boolean isHouseholdInUse(Owner owner) throws DataAccessException {
411	        String householdId = owner.getHouseholdId() != null
412	            ? owner.getHouseholdId()
413	            : householdIdFor(owner.getLastName(), owner.getPostcode());
414	        return ownerRepository.findAll().stream()
415	            .filter(existing -> existing != owner && existing.getId() != null)
416	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
417	    }
418	
419	    @Override
420	    @Transactional(readOnly = true)
421	    public String householdIdFor(String lastName, String postcode) throws DataAccessException {
422	        String key = normalizeHouseholdValue(lastName) + "|" + (postcode == null ? "" : postcode);
423	        return Sha256Hex.upperHexPrefix(key, 12);
424	    }
425	
426	    /**
427	     * Normalizes a household field (the last name) for duplicate comparison by trimming,
428	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
429	     * spaced but equivalent values compare equal.
430	     */
431	    private static String normalizeHouseholdValue(String value) {
432	        if (value == null) {
433	            return "";
434	        }
435	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
436	    }
437	
438	    /**
439	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
440	     * owners that share its {@code householdId}. Owners without a household id are left at a count
441	     * of zero.
442	     *
443	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
444	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
445	     */
446	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
447	        if (!owners.isEmpty()) {
448	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
449	                .filter(owner -> owner.getHouseholdId() != null)
450	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
451	            for (Owner owner : owners) {
452	                long size = owner.getHouseholdId() == null
453	                    ? 0L
454	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
455	                owner.setHouseholdMemberCount((int) size);
456	            }
457	        }
458	        return result;
459	    }
460	
461	    /**
462	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
463	     */
464	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
465	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
466	    }
