45	/**
46	 * Global Exception handler for REST controllers.
47	 * <p>
48	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
49	 *
50	 * @author Vitaliy Fedoriv
51	 * @author Alexander Dudkin
52	 */
53	@ControllerAdvice
54	public class ExceptionControllerAdvice {
55	
56	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
57	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
58	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
59	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
60	
61	    /**
62	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
63	     * class.
64	     *
65	     * @param e     Object referring to the thrown exception.
66	     * @param status HTTP response status.
67	     * @param url URL request.
68	     */
69	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
70	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
71	        problemDetail.setType(URI.create(url.toString()));
72	        problemDetail.setTitle(e.getClass().getSimpleName());
73	        problemDetail.setDetail(detail);
74	        problemDetail.setProperty("timestamp", Instant.now());
75	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
76	        return problemDetail;
77	    }
78	
79	    /**
80	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
81	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
82	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
83	     * would catch it and report an authorization failure as a 500.
84	     *
85	     * @param e The {@link AccessDeniedException} to propagate
86	     * @throws AccessDeniedException always
87	     */
88	    @ExceptionHandler(AccessDeniedException.class)
89	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
90	        throw e;
91	    }
92	
93	    /**
94	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
95	     *
96	     * @param e The {@link Exception} to be handled
97	     * @param request {@link HttpServletRequest} object referring to the current request.
98	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
99	     */
100	    @ExceptionHandler(Exception.class)
101	    @ResponseBody
102	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
103	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
104	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
105	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
106	        return ResponseEntity.status(status).body(detail);
107	    }
108	
109	    /**
110	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
111	     * method returns a 404 Not Found status if an entity does not exist.
112	     *
113	     * @param e The {@link DataIntegrityViolationException} to be handled
114	     * @param request {@link HttpServletRequest} object referring to the current request.
115	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
116	     */
117	    @ExceptionHandler(DataIntegrityViolationException.class)
118	    @ResponseBody
119	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
120	        logger.warn("Data integrity violation at {} {}: {}",
121	            request.getMethod(),
122	            request.getRequestURI(),
123	            e.getMessage());
124	        logger.debug("Data integrity violation stacktrace", e);
125	        HttpStatus status = HttpStatus.NOT_FOUND;
126	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
127	        return ResponseEntity.status(status).body(detail);
128	    }
129	
130	    /**
131	     * Handles {@link InvalidTelephoneException} thrown while normalizing a telephone number into
132	     * E.164 form, returning a 400 Bad Request so a number that cannot form a valid E.164 value is
133	     * rejected rather than surfacing as an unexpected 500.
134	     *
135	     * @param e The {@link InvalidTelephoneException} to be handled
136	     * @param request {@link HttpServletRequest} object referring to the current request.
137	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
138	     */
139	    @ExceptionHandler(InvalidTelephoneException.class)
140	    @ResponseBody
141	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
142	        logger.debug("Invalid telephone at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
143	        HttpStatus status = HttpStatus.BAD_REQUEST;
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
145	        return ResponseEntity.status(status).body(detail);
146	    }
