195	    public ResponseEntity<ProblemDetail> handleInvalidRegistrationDateException(InvalidRegistrationDateException e, HttpServletRequest request) {
196	        logger.debug("Invalid registration date at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
