202	    /**
203	     * Handles exception thrown by Bean Validation on controller methods parameters
204	     *
205	     * @param e The {@link MethodArgumentNotValidException} to be handled
206	     * @param request {@link HttpServletRequest} object referring to the current request.
207	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
208	     */
209	    @ExceptionHandler(MethodArgumentNotValidException.class)
210	    @ResponseBody
211	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
212	        HttpStatus status = HttpStatus.BAD_REQUEST;
213	        BindingErrorsResponse errors = new BindingErrorsResponse();
214	        BindingResult bindingResult = e.getBindingResult();
215	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
216	        if (bindingResult.hasErrors()) {
217	            errors.addAllErrors(bindingResult);
218	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
219	                .map(FieldError::getField)
220	                .distinct()
221	                .toList();
222	            detail.setProperty("errors", invalidFields);
223	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
224	                .map(fieldError -> {
225	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
226	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
227	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
228	                        fieldError.getField(),
229	                        defaultMessage,
230	                        rejectedValue);
231	                    return new ValidationMessageDto(message)
232	                        .putAdditionalProperty("field", fieldError.getField())
233	                        .putAdditionalProperty("rejectedValue", rejectedValue)
234	                        .putAdditionalProperty("defaultMessage", defaultMessage);
235	                })
236	                .toList();
237	            logger.debug("Validation error at {} {}: {}",
238	                request.getMethod(),
239	                request.getRequestURI(),
240	                bindingResult.getFieldErrors());
241	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
242	            return ResponseEntity.status(status).body(detail);
243	        }
244	        return ResponseEntity.status(status).body(detail);
245	    }
